body:
`formatNumberSpec()` can throw at runtime for invalid option combinations (e.g. `style: 'currency'` without `currency`, or `style: 'unit'` without `unit`). Since `currency`/`unit` are optional in `SpecNumberFormat`, consider validating these cases and either defaulting (like `formatCurrency` does) or falling back to a safe `'decimal'` format instead of throwing.
```suggestion
  const requestedStyle: SpecNumberFormat['style'] = format.style || 'decimal';

  // Normalize style to avoid Intl.NumberFormat runtime errors:
  // - 'currency' requires a currency code
  // - 'unit' requires a unit identifier
  const effectiveStyle: Intl.NumberFormatOptions['style'] =
    requestedStyle === 'currency' && !format.currency
      ? 'decimal'
      : requestedStyle === 'unit' && !format.unit
        ? 'decimal'
        : requestedStyle;

  const options: Intl.NumberFormatOptions = {
    style: effectiveStyle,
  };

  if (effectiveStyle === 'currency' && format.currency) {
    options.currency = format.currency;
  }

  if (effectiveStyle === 'unit' && format.unit) {
    options.unit = format.unit;
  }

  if (format.minimumFractionDigits !== undefined) {
    options.minimumFractionDigits = format.minimumFractionDigits;
  }

  if (format.maximumFractionDigits !== undefined) {
    options.maximumFractionDigits = format.maximumFractionDigits;
  }

  if (format.useGrouping !== undefined) {
    options.useGrouping = format.useGrouping;
  }
```
